        public static bool TryGet(string abilityId, out GameThreeAbilityCatalogItem item)
        {
            foreach (var candidate in All)
            {
                if (string.Equals(candidate.AbilityId, abilityId, System.StringComparison.OrdinalIgnoreCase))
                {
                    item = candidate;
                    return true;
                }
            }

            item = null!;
            return false;
        }
    }
